// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        amount = bound(amount, 1, 1e30);

        vm.deal(actor, amount);
        vm.startPrank(actor);
        c.addToBalance{value: amount}();
        uint256 contractBalanceAfterDeposit = address(c).balance;
        vm.assume(contractBalanceAfterDeposit == amount);
        c.withdrawBalance();
        vm.stopPrank();

        // Rule: after a successful withdrawal the contract no longer holds the withdrawn funds,
        // and the caller's recorded balance is zeroed.
        assertTrue(address(c).balance == contractBalanceAfterDeposit - amount && c.getBalance(actor) == 0);
    }
}
